(()=>{'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem('oil-ui-demo:'+k))??f}catch{return f}},save=(k,v)=>localStorage.setItem('oil-ui-demo:'+k,JSON.stringify(v));
const seed=[{id:'CM-201',title:'会议室无线投屏终端，连接后画面间歇冻结',owner:'周宁',status:'待确认',updated:'10:18'},{id:'CM-202',title:'东区条码扫描终端 A-17',owner:'林安',status:'维修中',updated:'10:16'},{id:'CM-203',title:'访客登记平板',owner:'陈禾',status:'已完成',updated:'昨天 18:40'}];
let rows=read('rows',seed),mode='W01',query='',selected=rows[1].id,detail=false,checked=new Set(),date='周一',paused=false,timer=null,events=0,condition='ready';
const types=[['W01','队列'],['W02','表格'],['W03','主从详情'],['W04','看板'],['W05','日程'],['W06','编辑器'],['W07','画布'],['W08','图关系'],['W09','监控'],['W10','检索分析']];
const hints={W01:'逐项处理：优先级 → 当前对象 → 确认结果',W02:'列间比较与批处理：对象一致，字段可比较',W03:'对象与上下文并置：切换详情，保留列表',W04:'按允许的阶段流转：看见在制品与瓶颈',W05:'时间与占用：先选日期，再选可用时段',W06:'围绕一个内容对象：草稿、编辑与保存',W07:'空间是数据：选择、移动并保存位置',W08:'关系比位置重要：查看上下游与影响',W09:'关注变化与异常：暂停后明确停止更新',W10:'从问题到证据：检索、筛选、展开来源'};
function note(text){$('#feedback').textContent=text}
function filtered(){return rows.filter(r=>(r.id+r.title+r.owner+r.status).includes(query))}
const toolbar=()=>`<div class="toolbar"><label for="query">定位工单</label><input id="query" value="${esc(query)}" placeholder="搜索设备、编号或提交人"><button id="clear">清除</button><span class="muted">${filtered().length} 项</span></div>`;
const rowHtml=r=>`<li class="row" aria-current="${selected===r.id}"><div class="row-main"><button class="link-button choose" data-id="${r.id}">${esc(r.title)}</button><small>${r.id} · ${r.owner} · ${r.updated}</small></div><span class="badge ${r.status==='已完成'?'good':''}">${r.status}</span></li>`;
function details(){const r=rows.find(r=>r.id===selected)||rows[0];return `<article class="detail panel"><button class="mobile-back" id="back">← 返回列表</button><p class="eyebrow">${r.id} / 设备维修</p><h2 tabindex="-1" id="detail-title">${esc(r.title)}</h2><dl><dt>当前状态</dt><dd id="current-status">${r.status}</dd><dt>提交人</dt><dd>${r.owner}</dd><dt>故障描述</dt><dd>设备在连续会议中约每十分钟断连一次，重启后暂时恢复。请在现场记录信号与供电状态，处理结果仍需复现确认。</dd></dl><button class="primary" id="handle" ${r.status==='已完成'?'disabled':''}>标记处理完成</button><small>本地合成记录；刷新可读回本次修改。</small></article>`}
function render(){if(timer){clearInterval(timer);timer=null}$('#modes').innerHTML=types.map(([id,label])=>`<button data-mode="${id}" aria-current="${mode===id}">${label}　<small>${id.slice(1)}</small></button>`).join('');let body='';
if(['W01','W02','W03'].includes(mode)){body=toolbar();if(condition!=='ready'){const labels={loading:'正在获取维修记录…',empty:query?'没有符合筛选的记录':'暂无维修记录',error:'加载失败，已保留筛选条件',permission:'你无权查看这组维修记录',offline:'已离线，上次数据仍保留，操作暂停'};body+=`<div class="panel pad" role="status">${labels[condition]} ${['error','offline'].includes(condition)?'<button id="retry">重新加载</button>':''}</div>`}else if(!filtered().length){body+='<p class="panel pad">没有匹配项。<button id="reset-query">清除筛选</button></p>'}else if(mode==='W02'){body+=`<div class="toolbar"><button id="bulk" ${!checked.size?'disabled':''}>标记已选 ${checked.size} 项完成</button></div><div class="panel table-scroll"><table><thead><tr><th>选择</th><th>编号</th><th>设备</th><th>提交人</th><th>状态</th></tr></thead><tbody>${filtered().map(r=>`<tr><td><input type="checkbox" aria-label="选择 ${r.id}" data-check="${r.id}" ${checked.has(r.id)?'checked':''}></td><td>${r.id}</td><td class="title">${esc(r.title)}</td><td>${r.owner}</td><td><span class="badge">${r.status}</span></td></tr>`).join('')}</tbody></table></div>`}else{body+=`<div class="split" data-detail="${detail}"><div class="panel master"><ul class="rows">${filtered().map(rowHtml).join('')}</ul></div>${details()}</div>`}body+=`<details class="state-controls"><summary>原型状态演示（非业务入口）</summary><div class="toolbar">${['ready','loading','empty','error','permission','offline'].map(x=>`<button data-condition="${x}">${x}</button>`).join('')}</div></details>`}
if(mode==='W04')body=`<div class="board">${['待确认','维修中','已完成'].map((s,i)=>`<section class="column"><h3>${s}</h3>${rows.filter(r=>r.status===s).map(r=>`<article class="task"><small>${r.id}</small><h3>${esc(r.title)}</h3><p>${r.owner}</p>${i<2?`<button data-move="${r.id}">推进至${i===0?'维修中':'已完成'}</button>`:'<span class="badge good">处理结束</span>'}</article>`).join('')||'<p class="muted">当前没有任务</p>'}</section>`).join('')}</div>`;
if(mode==='W05'){let a=read('appointments',[]);body=`<div class="week">${['周一','周二','周三','周四','周五'].map(d=>`<button data-date="${d}" aria-pressed="${date===d}">${d}</button>`).join('')}</div><section class="panel pad stack"><h2>${date} / 维修时段</h2>${['09:00','11:00','14:00'].map(t=>`<div class="row"><span>${t} – ${Number(t.slice(0,2))+1}:00</span><button data-book="${t}" ${a.includes(date+t)?'disabled':''}>${a.includes(date+t)?'已预约':'预约现场检修'}</button></div>`).join('')}</section>`}
if(mode==='W06'){let d=read('draft','检查设备接线与电源，然后记录复现步骤。'),s=read('document','');body=`<div class="editor panel pad"><div class="stack"><label for="editor">检修手册 / 内容</label><textarea id="editor">${esc(d)}</textarea><button class="primary" id="save-doc">保存文档</button><p id="draft-label" role="status">${d===s?'已保存':'本地草稿 · 尚未保存为文档'}</p></div><aside><h3>文档信息</h3><p class="muted">自动保留本地草稿；显式保存形成当前文档。</p><button id="restore-doc">恢复已保存版本</button></aside></div>`}
if(mode==='W07'){const p=read('position',{x:30,y:40});body=`<div class="toolbar"><button data-dx="-10">← 左移</button><button data-dx="10">右移 →</button><button data-dy="-10">↑ 上移</button><button data-dy="10">下移 ↓</button><button id="save-canvas">保存位置</button></div><div class="canvas" id="canvas"><button class="canvas-node" id="canvas-node" style="left:${p.x}px;top:${p.y}px">检修区 A<span class="muted"> / 选中后用方向键移动</span></button></div><p class="muted" id="position">位置 ${p.x}, ${p.y}</p>`}
if(mode==='W08')body=`<div class="panel pad"><div class="graph"><svg viewBox="0 0 600 350" preserveAspectRatio="none" aria-hidden="true"><path d="M90 170L300 70L510 170M90 170L300 280L510 170" fill="none" stroke="#a2b8aa" stroke-width="2"/></svg>${[['接入终端',15,49],['无线网络',50,20],['供电系统',50,80],['会议投屏',85,49]].map(([s,x,y])=>`<button data-node="${s}" style="left:${x}%;top:${y}%">${s}</button>`).join('')}</div><div id="node-detail" class="notice" aria-live="polite">选择一个节点查看依赖。也可用 Tab 定位。</div></div>`;
if(mode==='W09')body=`<section class="panel pad"><div class="metric-strip"><div><small>合成终端在线</small><strong>28 / 30</strong></div><div><small>当前异常</small><strong>2</strong></div><div><small>采样事件</small><strong id="event-count">${events}</strong></div></div><svg class="spark" viewBox="0 0 800 140" preserveAspectRatio="none" role="img" aria-label="合成负载趋势，小幅波动"><path d="M0 110L50 90L100 98L150 60L200 88L260 70L320 80L380 40L440 65L500 50L550 55L610 35L670 62L730 45L800 50" fill="none" stroke="#2457d6" stroke-width="3"/></svg><button id="pause">${paused?'继续事件流':'暂停事件流'}</button><p id="stream-state" class="status-line">${paused?'已暂停，显示最后一次采样':'合成事件流，每秒更新'}</p><ul class="rows" id="event-list"></ul></section>`;
if(mode==='W10')body=`<div class="toolbar"><label for="analysis-query">证据检索</label><input id="analysis-query" placeholder="输入 网络、供电 或 全部"><button class="primary" id="search-evidence">检索</button></div><div id="results"><p class="muted">从维修日志查找依据，展开查看来源，不伪造在线检索。</p></div>`;
$('#work').innerHTML=`<p class="eyebrow">${mode} / ${types.find(t=>t[0]===mode)[1]}</p><h2 style="margin:6px 0 20px">${hints[mode]}</h2>${body}`;bind();if(mode==='W09'&&!paused)timer=setInterval(()=>{events++;$('#event-count').textContent=events;$('#event-list').innerHTML=`<li class="row">终端心跳正常 <small>合成采样 ${events}</small></li>`},1000)}
function persist(){save('rows',rows)}
function bind(){$$('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;condition='ready';note('');render()});const q=$('#query');if(q)q.oninput=()=>{const pos=q.selectionStart;query=q.value;render();$('#query').focus();$('#query').setSelectionRange(pos,pos)};['#clear','#reset-query'].forEach(s=>{if($(s))$(s).onclick=()=>{query='';render();$('#query').focus()}});$$('.choose').forEach(b=>b.onclick=()=>{selected=b.dataset.id;detail=true;render();$('#detail-title').focus()});if($('#back'))$('#back').onclick=()=>{detail=false;render();$(`.choose[data-id="${selected}"]`)?.focus()};if($('#handle'))$('#handle').onclick=()=>{rows.find(r=>r.id===selected).status='已完成';persist();render();$('#detail-title').focus();note('已在本地标记完成；记录可刷新读回')};$$('[data-check]').forEach(b=>b.onchange=()=>{b.checked?checked.add(b.dataset.check):checked.delete(b.dataset.check);render();$(`[data-check="${b.dataset.check}"]`).focus()});if($('#bulk'))$('#bulk').onclick=()=>{rows.forEach(r=>{if(checked.has(r.id))r.status='已完成'});persist();const n=checked.size;checked.clear();render();note(`已更新 ${n} 项合成记录`)};$$('[data-condition]').forEach(b=>b.onclick=()=>{condition=b.dataset.condition;render()});if($('#retry'))$('#retry').onclick=()=>{condition='ready';render();note('合成数据已恢复，筛选保留')};$$('[data-move]').forEach(b=>b.onclick=()=>{let r=rows.find(r=>r.id===b.dataset.move);r.status=r.status==='待确认'?'维修中':'已完成';persist();render();note(`${r.id} 已推进至${r.status}`)});$$('[data-date]').forEach(b=>b.onclick=()=>{date=b.dataset.date;render()});$$('[data-book]').forEach(b=>b.onclick=()=>{let a=read('appointments',[]);a.push(date+b.dataset.book);save('appointments',a);render();note(`${date} ${b.dataset.book} 已预约（本地合成记录）`)});if($('#editor'))$('#editor').oninput=()=>{save('draft',$('#editor').value);$('#draft-label').textContent='本地草稿 · 尚未保存为文档'};if($('#save-doc'))$('#save-doc').onclick=()=>{save('document',$('#editor').value);$('#draft-label').textContent='已保存';note('文档已保存到本地演示存储')};if($('#restore-doc'))$('#restore-doc').onclick=()=>{save('draft',read('document',''));render();$('#editor').focus()};
function move(dx,dy){const e=$('#canvas-node'),c=$('#canvas');let x=Math.max(0,Math.min(c.clientWidth-e.offsetWidth,parseFloat(e.style.left)+dx)),y=Math.max(0,Math.min(c.clientHeight-e.offsetHeight,parseFloat(e.style.top)+dy));e.style.left=x+'px';e.style.top=y+'px';$('#position').textContent=`位置 ${x}, ${y} · 尚未保存`}
$$('[data-dx],[data-dy]').forEach(b=>b.onclick=()=>move(Number(b.dataset.dx||0),Number(b.dataset.dy||0)));if($('#canvas-node'))$('#canvas-node').onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();move(e.key==='ArrowLeft'?-10:e.key==='ArrowRight'?10:0,e.key==='ArrowUp'?-10:e.key==='ArrowDown'?10:0)}};if($('#save-canvas'))$('#save-canvas').onclick=()=>{let e=$('#canvas-node');save('position',{x:parseFloat(e.style.left),y:parseFloat(e.style.top)});note('空间位置已保存')};$$('[data-node]').forEach(b=>b.onclick=()=>{$('#node-detail').textContent=b.dataset.node==='会议投屏'?'会议投屏 ← 无线网络、供电系统；故障会影响接入终端。':`${b.dataset.node} → 会议投屏；点击相关节点继续追踪。`});if($('#pause'))$('#pause').onclick=()=>{paused=!paused;render();$('#pause').focus()};if($('#search-evidence'))$('#search-evidence').onclick=()=>{const q=$('#analysis-query').value.trim();let data=[['网络','CM-201 · 10:18','信号衰减伴随投屏冻结；现场日志中的观察，尚待复现确认。'],['供电','CM-202 · 10:16','检查电源适配器输出，维修中，不能据此推断已修复。']].filter(r=>q==='全部'||r[0].includes(q));$('#results').innerHTML=data.length?data.map(r=>`<details class="evidence"><summary>${r[0]} · ${r[1]}</summary><p>${r[2]}</p><small>来源：本页合成维修日志，非在线搜索。</small></details>`).join(''):'<p class="notice">没有结果，保留查询后可调整条件。</p>'};}
$('#more-modes').onclick=()=>{const nav=$('#modes'),atEnd=nav.scrollLeft+nav.clientWidth>=nav.scrollWidth-4;nav.scrollBy({left:atEnd?-nav.scrollWidth:nav.clientWidth*.85,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})};$('#modes').addEventListener('scroll',()=>{const nav=$('#modes'),atEnd=nav.scrollLeft+nav.clientWidth>=nav.scrollWidth-4;$('#more-modes').textContent=atEnd?'返回 ←':'更多 →';$('#more-modes').setAttribute('aria-label',atEnd?'返回前面的工作区选项':'向后浏览更多工作区')});render();window.addEventListener('pagehide',()=>clearInterval(timer));})();
